use super::*;
fn engine()->Engine {Engine::new(fs::read(std::env::var("AKAGI_WEIGHTS_PATH").expect("explicit external test weights")).unwrap(),4,0).unwrap()}
fn hand()->Value {json!(["2m","3m","4m","5m","6m","7m","2p","3p","4p","5p","6p","7p","5s"])}
fn prefix(seat:u8)->Vec<Value>{let mut hands=vec![json!(vec!["?";13]);4];hands[seat as usize]=hand();vec![json!({"type":"start_game","id":seat,"names":["Player 0","Player 1","Player 2","Player 3"]}),json!({"type":"start_kyoku","bakaze":"E","kyoku":1,"honba":0,"kyotaku":0,"oya":0,"scores":[25000,25000,25000,25000],"dora_marker":"9s","tehais":hands})]}
fn feed(e:&mut Engine,events:&[Value],checked:bool){for v in events{let mut v=v.clone();if v["type"]=="start_game"{v["id"]=json!("audit");}let ev=serde_json::from_value(v).unwrap();if checked{e.feed_checked(ev)}else{e.feed(ev)}}}
fn request(seat:u8,events:Vec<Value>)->Value{json!({"protocol":PROTOCOL,"requestId":"stage0","seat":seat,"events":events})}
#[test] fn external_official_pytorch_parity(){let json:Value=serde_json::from_str(include_str!("../vendor/native_bot/tests/fixtures/parity_4p.json")).unwrap();let model=native_bot::model::Model::from_safetensors(fs::read(std::env::var("AKAGI_WEIGHTS_PATH").unwrap()).unwrap(),4).unwrap();let input:Vec<f32>=serde_json::from_value(json["input"].clone()).unwrap();let reference:Vec<f32>=serde_json::from_value(json["logits"].clone()).unwrap();let got=model.forward_logits(&input).unwrap();let diff=got.iter().zip(&reference).map(|(a,b)|(a-b).abs()).fold(0f32,f32::max);assert!(diff<2e-3,"{diff}");let arg=got.iter().enumerate().max_by(|a,b|a.1.total_cmp(b.1)).unwrap().0;assert_eq!(arg,json["argmax"].as_u64().unwrap() as usize);eprintln!("official PyTorch max abs diff={diff}");}
#[test] fn four_seats_a_b_a_and_self_discard(){let mut e=engine();for seat in 0..4{let mut a=prefix(seat);a.push(json!({"type":"tsumo","actor":seat,"pai":"C"}));let a=request(seat,a);let first=replay(&mut e,&a,true).unwrap();let mut b=prefix((seat+1)%4);b.push(json!({"type":"tsumo","actor":(seat+1)%4,"pai":"E"}));replay(&mut e,&request((seat+1)%4,b),true).unwrap();assert_eq!(first,replay(&mut e,&a,true).unwrap());assert_eq!(first["action"]["actor"],seat);}}
#[test] fn unknown_and_legal_hidden_fills_four_seats(){for seat in 0..4 {for mode in 0..3 {let mut p=prefix(seat);let other=(seat+1)%4;if mode==0{p.push(json!({"type":"tsumo","actor":seat,"pai":"C"}));}else{p.push(json!({"type":"tsumo","actor":other,"pai":"?"}));if mode==2{p.push(json!({"type":"ankan","actor":other,"consumed":["N","N","N","N"]}));p.push(json!({"type":"dora","dora_marker":"1s"}));p.push(json!({"type":"tsumo","actor":other,"pai":"?"}));}p.push(json!({"type":"dahai","actor":other,"pai":"C","tsumogiri":true}));}
 let mut base=engine();base.set_seat(seat);base.set_rule(GameRule::default_mjsoul());feed(&mut base,&p,true);let want=base.snapshot().unwrap();let want_action=base.decide().unwrap().map(|d|d.action);
 // Synthetic complete assignments use only the residual physical deck. Calls reserve their public tiles.
 for reverse in [false,true] {let mut filled=p.clone();let mut deck:Vec<u8>=(0..136).collect();let remove=|deck:&mut Vec<u8>,tile:&str|{let t=mjai_to_tid(tile).unwrap();if let Some(i)=deck.iter().position(|x|x/4==t/4 && native_bot::tiles::is_aka(*x)==native_bot::tiles::is_aka(t)){deck.remove(i);}};for t in hand().as_array().unwrap(){remove(&mut deck,t.as_str().unwrap());}remove(&mut deck,"9s");remove(&mut deck,"C");if mode==2{for _ in 0..4{remove(&mut deck,"N");}remove(&mut deck,"1s");remove(&mut deck,"E");}if reverse{deck.reverse();}
 for s in 0..4 {if s!=seat{let mut h=Vec::new();if mode==2 && s==other{h.extend(vec!["N".to_string();4]);}while h.len()<13{h.push(riichienv_core::parser::tid_to_mjai(deck.pop().unwrap()));}filled[1]["tehais"][s as usize]=json!(h);}}
 let mut draws=0;for v in filled.iter_mut().skip(2){if v["type"]=="tsumo" && v["actor"]!=seat {v["pai"]=if mode==2 && draws==0 {json!("E")}else{json!("C")};draws+=1;}}
 let mut e=engine();e.set_seat(seat);e.set_rule(GameRule::default_mjsoul());feed(&mut e,&filled,true);assert_eq!(want,e.snapshot().unwrap(),"seat={seat} mode={mode}");assert_eq!(want_action,e.decide().unwrap().map(|d|d.action));}
}}}
#[test] fn declined_ron_temporary_and_riichi_furiten(){for riichi in [false,true] {let mut e=engine();e.set_rule(GameRule::default_mjsoul());let mut p=prefix(0);if riichi{p.push(json!({"type":"reach","actor":0}));p.push(json!({"type":"reach_accepted","actor":0}));}p.push(json!({"type":"tsumo","actor":1,"pai":"?"}));p.push(json!({"type":"dahai","actor":1,"pai":"5s","tsumogiri":true}));feed(&mut e,&p,true);assert_eq!(e.snapshot().unwrap().1[79],1,"ron fixture");feed(&mut e,&[json!({"type":"tsumo","actor":2,"pai":"?"}),json!({"type":"dahai","actor":2,"pai":"5s","tsumogiri":true})],true);assert_eq!(e.snapshot().unwrap().1[79],0,"declined ron must be furiten");}}
#[test] fn mjsoul_ankan_kokushi_rule_and_furiten(){let mut p=prefix(0);p[1]["tehais"][0]=json!(["1m","1m","9m","1p","9p","1s","9s","E","S","W","P","F","C"]);p.push(json!({"type":"tsumo","actor":1,"pai":"?"}));p.push(json!({"type":"ankan","actor":1,"consumed":["N","N","N","N"]}));let mut a=engine();feed(&mut a,&p,true);assert_eq!(a.snapshot().unwrap().1[79],0,"Tenhou no closed-kan rob");let mut b=engine();b.set_rule(GameRule::default_mjsoul());feed(&mut b,&p,true);assert_eq!(b.snapshot().unwrap().1[79],1,"MJSoul kokushi closed-kan rob");}
#[test] fn guards_and_strict_events(){let mut e=engine();let mut p=prefix(0);p.push(json!({"type":"tsumo","actor":0,"pai":"C"}));let mut q=request(0,p.clone());q["events"].as_array_mut().unwrap().push(json!({"type":"reach_accepted","actor":0}));assert_eq!(replay(&mut e,&q,false).unwrap_err().to_string(),"UNSUPPORTED_TRAILING_ANNOUNCEMENT");q=request(0,p.clone());q["events"].as_array_mut().unwrap().push(json!({"type":"ankan","actor":0,"consumed":["C","C","C","C"]}));assert!(replay(&mut e,&q,false).is_err());q=request(0,p.clone());q["events"].as_array_mut().unwrap().insert(2,json!({"type":"future_event"}));assert!(replay(&mut e,&q,false).is_err());q=request(0,p);q["events"][1]["tehais"][1][0]=json!("1m");assert!(replay(&mut e,&q,false).is_err());}
#[test] fn reach_paired_entity_uses_real_drawn_tile(){let mut e=engine();let mut p=prefix(0);p.push(json!({"type":"tsumo","actor":0,"pai":"9m"}));p.push(json!({"type":"reach","actor":0}));let result=replay(&mut e,&request(0,p),true).unwrap();assert_eq!(result["action"]["type"],"dahai");assert_eq!(result["action"]["actor"],0);}

#[test] fn hidden_fills_calls_and_supplementary_draws(){for seat in 0..4 {for kind in ["chi","pon","daiminkan"] {
 let caller=(seat+2)%4;let from=(seat+1)%4;let fourth=(seat+3)%4;
 let (pai,consumed)=match kind {"chi"=>("2s",vec!["1s","3s"]),"pon"=>("7s",vec!["7s","7s"]),_=>("8s",vec!["8s","8s","8s"])};
 let mut events=prefix(seat);events[1]["oya"]=json!(from);events[1]["kyoku"]=json!(from+1);
 events.extend([json!({"type":"tsumo","actor":from,"pai":"?"}),json!({"type":"dahai","actor":from,"pai":pai,"tsumogiri":true}),json!({"type":kind,"actor":caller,"target":from,"pai":pai,"consumed":consumed})]);
 if kind=="daiminkan" {events.extend([json!({"type":"dora","dora_marker":"4s"}),json!({"type":"tsumo","actor":caller,"pai":"?"})]);}
 events.extend([json!({"type":"dahai","actor":caller,"pai":"C","tsumogiri":kind=="daiminkan"}),json!({"type":"tsumo","actor":fourth,"pai":"?"}),json!({"type":"dahai","actor":fourth,"pai":"F","tsumogiri":true}),json!({"type":"tsumo","actor":seat,"pai":"E"})]);
 let mut base=engine();base.set_seat(seat);base.set_rule(GameRule::default_mjsoul());feed(&mut base,&events,true);let expected=base.snapshot().unwrap();let expected_action=base.decide().unwrap().map(|d|d.action);
 for reverse in [false,true] {let mut full=events.clone();let mut deck:Vec<u8>=(0..136).collect();let take=|deck:&mut Vec<u8>,tile:&str|{let t=mjai_to_tid(tile).unwrap();let i=deck.iter().position(|x|x/4==t/4 && native_bot::tiles::is_aka(*x)==native_bot::tiles::is_aka(t)).unwrap();deck.remove(i);};for t in hand().as_array().unwrap(){take(&mut deck,t.as_str().unwrap());}for t in ["9s","E","F","C",pai]{take(&mut deck,t);}for t in &consumed{take(&mut deck,t);}if kind=="daiminkan"{take(&mut deck,"4s");}if reverse{deck.reverse();}
 for s in 0..4 {if s!=seat {let mut h=vec![];if s==caller{h.extend(consumed.iter().map(|x|x.to_string()));if kind!="daiminkan"{h.push("C".into());}}while h.len()<13{h.push(riichienv_core::parser::tid_to_mjai(deck.pop().unwrap()));}full[1]["tehais"][s as usize]=json!(h);}}
 for e in full.iter_mut().skip(2){if e["type"]=="tsumo" && e["actor"]!=seat {e["pai"]=if e["actor"]==from{json!(pai)}else if e["actor"]==caller{json!("C")}else{json!("F")};}}
 let mut e=engine();e.set_seat(seat);e.set_rule(GameRule::default_mjsoul());feed(&mut e,&full,true);assert_eq!(expected,e.snapshot().unwrap(),"{seat} {kind}");assert_eq!(expected_action,e.decide().unwrap().map(|d|d.action));}
}}}
#[test] fn temporary_furiten_is_consumed_once_and_riichi_persists(){for riichi in [false,true] {let mut e=engine();e.set_rule(GameRule::default_mjsoul());let mut p=prefix(0);if riichi{p.extend([json!({"type":"reach","actor":0}),json!({"type":"reach_accepted","actor":0})]);}p.extend([json!({"type":"tsumo","actor":3,"pai":"?"}),json!({"type":"dahai","actor":3,"pai":"5s","tsumogiri":true})]);feed(&mut e,&p,true);assert_eq!(e.snapshot().unwrap().1[79],1);feed(&mut e,&[json!({"type":"tsumo","actor":0,"pai":"C"}),json!({"type":"dahai","actor":0,"pai":"C","tsumogiri":true}),json!({"type":"tsumo","actor":1,"pai":"?"}),json!({"type":"dahai","actor":1,"pai":"5s","tsumogiri":true})],true);assert_eq!(e.snapshot().unwrap().1[79],if riichi{0}else{1});}}
#[test] fn kan_supplement_ron_context_and_call_cancels_first_turn(){let mut e=engine();e.set_rule(GameRule::default_mjsoul());let mut p=prefix(0);p[1]["tehais"][0]=json!(["1m","1m","1m","2m","3m","4p","5p","6p","7s","8s","9s","E","E"]);p.extend([json!({"type":"tsumo","actor":3,"pai":"?"}),json!({"type":"dahai","actor":3,"pai":"1m","tsumogiri":true}),json!({"type":"daiminkan","actor":0,"target":3,"pai":"1m","consumed":["1m","1m","1m"]}),json!({"type":"dora","dora_marker":"2s"}),json!({"type":"tsumo","actor":0,"pai":"4m"})]);feed(&mut e,&p,true);assert_eq!(e.snapshot().unwrap().1[79],1,"rinshan is the only yaku");}
#[test] fn no_yaku_shape_causes_same_turn_furiten(){let mut e=engine();let mut p=prefix(0);p[1]["tehais"][0]=json!(["1m","2m","3m","7p","8p","9p","7s","8s","9s","2p","3p","E","E"]);p.extend([json!({"type":"tsumo","actor":1,"pai":"?"}),json!({"type":"dahai","actor":1,"pai":"4p","tsumogiri":true})]);feed(&mut e,&p,true);assert_eq!(e.snapshot().unwrap().1[79],0);feed(&mut e,&[json!({"type":"tsumo","actor":2,"pai":"?"}),json!({"type":"dahai","actor":2,"pai":"1p","tsumogiri":true})],true);assert_eq!(e.snapshot().unwrap().1[79],0,"passed no-yaku shape makes next chanta ron furiten");}
